const stopWebhook = `-- name: StopWebhook :exec
UPDATE webhooks SET stopped_at = coalesce(stopped_at, now()) WHERE workspace_id = $1 AND url = $2
`

type StopWebhookParams struct {
	WorkspaceID uuid.UUID
	Url         string
}

// Deliveries stop only while the URL is still the one whose server answered 410 Gone; stopping again
// keeps the time they first stopped.
func (q *Queries) StopWebhook(ctx context.Context, arg StopWebhookParams) error {
	_, err := q.db.Exec(ctx, stopWebhook, arg.WorkspaceID, arg.Url)
	return err
}

const touchSession = `-- name: TouchSession :execrows
UPDATE sessions SET last_active_at = now()
WHERE workspace_id = $1 AND user_id = $2 AND id = $3 AND ended_at IS NULL
`

type TouchSessionParams struct {
	WorkspaceID uuid.UUID
	UserID      uuid.UUID
	ID          uuid.UUID
}

func (q *Queries) TouchSession(ctx context.Context, arg TouchSessionParams) (int64, error) {
	result, err := q.db.Exec(ctx, touchSession, arg.WorkspaceID, arg.UserID, arg.ID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const turnForRequest = `-- name: TurnForRequest :one
SELECT status FROM turns WHERE workspace_id = $1 AND session_id = $2 AND request_id = $3
`

type TurnForRequestParams struct {
	WorkspaceID uuid.UUID
	SessionID   uuid.UUID
	RequestID   uuid.UUID
}

func (q *Queries) TurnForRequest(ctx context.Context, arg TurnForRequestParams) (string, error) {
	row := q.db.QueryRow(ctx, turnForRequest, arg.WorkspaceID, arg.SessionID, arg.RequestID)
	var status string
	err := row.Scan(&status)
	return status, err
}

const turnInFlight = `-- name: TurnInFlight :one
SELECT EXISTS (
    SELECT FROM turns
    WHERE workspace_id = $1 AND session_id = $2 AND status = 'in_flight'
      AND created_at > now() - make_interval(secs => $3::float8)
) AS in_flight
`

type TurnInFlightParams struct {
	WorkspaceID     uuid.UUID
	SessionID       uuid.UUID
	DeadlineSeconds float64
}

func (q *Queries) TurnInFlight(ctx context.Context, arg TurnInFlightParams) (bool, error) {
	row := q.db.QueryRow(ctx, turnInFlight, arg.WorkspaceID, arg.SessionID, arg.DeadlineSeconds)
	var in_flight bool
	err := row.Scan(&in_flight)
	return in_flight, err
}

const userByReference = `-- name: UserByReference :one
SELECT user_id FROM user_references WHERE workspace_id = $1 AND reference = $2
`

type UserByReferenceParams struct {
	WorkspaceID uuid.UUID
	Reference   string
}

func (q *Queries) UserByReference(ctx context.Context, arg UserByReferenceParams) (uuid.UUID, error) {
	row := q.db.QueryRow(ctx, userByReference, arg.WorkspaceID, arg.Reference)
	var user_id uuid.UUID
	err := row.Scan(&user_id)
	return user_id, err
}

const userReference = `-- name: UserReference :one
SELECT reference FROM user_references WHERE workspace_id = $1 AND user_id = $2
`

type UserReferenceParams struct {
	WorkspaceID uuid.UUID
	UserID      uuid.UUID
}

// A user has at most one reference in a workspace, so it reads back from them.
func (q *Queries) UserReference(ctx context.Context, arg UserReferenceParams) (string, error) {
	row := q.db.QueryRow(ctx, userReference, arg.WorkspaceID, arg.UserID)
	var reference string
	err := row.Scan(&reference)
	return reference, err
}

const webhook = `-- name: Webhook :one
SELECT url, secret, (stopped_at IS NOT NULL)::boolean AS stopped FROM webhooks WHERE workspace_id = $1
`

type WebhookRow struct {
	Url     string
	Secret  string
	Stopped bool
}

func (q *Queries) Webhook(ctx context.Context, workspaceID uuid.UUID) (WebhookRow, error) {
	row := q.db.QueryRow(ctx, webhook, workspaceID)
	var i WebhookRow
	err := row.Scan(&i.Url, &i.Secret, &i.Stopped)
	return i, err
}
